"""Confirmed profile facts and bilingual first-consultation preparation."""
from html import escape
NAME='Kostyantyn Mykhalchenko'
DIRECTORY='https://members.nsbs.org/NSBSWEB/Lawyer_Search/Results_Page2.aspx?ID=125622'

def url(route,fr):return ('/fr/' if fr else '/')+route+'/'
def link(route,label,fr,cls='text-link'):return f'<a class="{cls}" href="{url(route,fr)}">{label}</a>'

def profile(fr):
 def t(en,fr_text):return fr_text if fr else en
 return f'''<section class="section lawyer-intro" aria-labelledby="meet-lawyer"><figure><img src="/assets/kostyantyn-courtroom.jpg" width="1600" height="900" loading="lazy" decoding="async" alt="{t('Kostyantyn Mykhalchenko in court dress in a courtroom','Kostyantyn Mykhalchenko en tenue d’avocat dans une salle d’audience')}"><figcaption>{NAME} · {t('Halifax, Nova Scotia','Halifax, Nouvelle-Écosse')}</figcaption></figure><div><span class="eyebrow">{t('MEET YOUR LAWYER','VOTRE AVOCAT')}</span><h2 id="meet-lawyer">{NAME}</h2><p class="profile-role">{t('Barrister, Solicitor &amp; Notary Public','Avocat et notaire public')}</p><p>Pavel Boubnov – Barrister &amp; Solicitor</p><p>{t('A direct point of contact for your legal questions in Halifax and across Nova Scotia. Start with your situation, your important dates and the next step you need to understand.','Un contact direct pour vos questions juridiques à Halifax et partout en Nouvelle-Écosse. Présentez votre situation, les dates importantes et la prochaine étape que vous souhaitez comprendre.')}</p><dl class="profile-facts"><div><dt>{t('Appointment languages','Langues de rendez-vous')}</dt><dd>{t('English · Ukrainian · Russian','Anglais · Ukrainien · Russe')}</dd></div><div><dt>{t('Serving','Région desservie')}</dt><dd>{t('Halifax &amp; Nova Scotia','Halifax et Nouvelle-Écosse')}</dd></div></dl><div class="actions">{link('about',t('Meet Kostyantyn →','Découvrir Kostyantyn →'),fr)}<a class="text-link" href="{DIRECTORY}">{t('Official NSBS directory ↗','Répertoire officiel de la NSBS ↗')}</a></div></div></section>'''

def preview(fr):
 def t(en,fr_text):return fr_text if fr else en
 rows=[(t('Tell us the basics','Présentez l’essentiel'),t('Share the general topic, important dates and your preferred appointment language.','Indiquez le sujet général, les dates importantes et la langue de rendez-vous souhaitée.')),(t('Confirm the arrangements','Confirmez les modalités'),t('Ask about availability, format, duration and consultation fees before booking.','Vérifiez la disponibilité, le mode, la durée et les honoraires avant de fixer le rendez-vous.')),(t('Prepare your questions','Préparez vos questions'),t('Keep relevant documents ready and ask how to share them securely.','Gardez les documents pertinents à portée de main et demandez comment les transmettre de façon sûre.'))]
 return '<section class="section steps consultation-preview"><div><span class="eyebrow">'+t('YOUR FIRST CONSULTATION','VOTRE PREMIÈRE CONSULTATION')+'</span><h2>'+t('Know what to expect.<br>Arrive prepared.','Sachez à quoi vous attendre.<br>Préparez votre entretien.')+'</h2><p>'+t('A clear starting point, whether you have one question or several documents to discuss.','Un point de départ clair, que vous ayez une question ou plusieurs documents à examiner.')+'</p>'+link('first-consultation',t('Your first-consultation guide →','Guide de première consultation →'),fr)+'</div><ol>'+''.join('<li><h3>'+h+'</h3><p>'+p+'</p></li>' for h,p in rows)+'</ol></section>'

def guide(fr):
 def t(en,fr_text):return fr_text if fr else en
 contact=url('contact',fr)+'#enquiry'
 rows=[
 (t('Availability','Disponibilité'),t('Ask whether the practice can assist with your type of matter and the dates involved.','Demandez si le cabinet peut vous aider pour ce type de dossier et les dates concernées.')),
 (t('Format & location','Mode et lieu'),t('Confirm whether the meeting will be in person or remote, and any address or joining instructions.','Confirmez si l’entretien se tiendra en personne ou à distance, ainsi que l’adresse ou les instructions de connexion.')),
 (t('Duration','Durée'),t('Ask how much time is available and which questions should be covered first.','Demandez le temps prévu et les questions à aborder en priorité.')),
 (t('Consultation fees','Honoraires de consultation'),t('Ask whether the initial consultation is paid, what it includes, and how any applicable fees and taxes are handled.','Demandez si la première consultation est payante, ce qu’elle comprend et les modalités des honoraires et taxes applicables.')),
 (t('Scope & next steps','Portée et prochaines étapes'),t('Clarify what can be discussed at the consultation and what would require a separate engagement.','Précisez ce qui peut être abordé pendant la consultation et ce qui nécessiterait un mandat distinct.')),
 ]
 checklist=[t('A short timeline of the main events','Une courte chronologie des événements principaux'),t('Any dates shown on notices, agreements or court papers','Les dates figurant dans les avis, ententes ou documents judiciaires'),t('Three questions you most want answered','Les trois questions auxquelles vous souhaitez surtout une réponse'),t('Relevant documents kept together for your own reference','Les documents pertinents regroupés pour votre référence'),t('Your preferred appointment language and any accessibility needs','Votre langue de rendez-vous souhaitée et vos besoins d’accessibilité')]
 questions=[(t('Is sending an enquiry the same as booking?', 'Une demande équivaut-elle à une réservation?'),t('No. The form sends an enquiry. Wait for the practice to confirm availability and appointment arrangements.','Non. Le formulaire transmet une demande. Attendez la confirmation de la disponibilité et des modalités par le cabinet.')),(t('Should I upload documents?', 'Dois-je téléverser des documents?'),t('The enquiry form does not accept uploads. Start with the general topic and ask the practice how to share documents securely.','Le formulaire n’accepte pas de documents. Commencez par le sujet général et demandez au cabinet comment transmettre les documents de façon sûre.')),(t('Can the consultation be in French?', 'La consultation peut-elle se dérouler en français?'),t('Appointments are offered in English, Ukrainian and Russian. The French website provides information and does not indicate French-language representation.','Les rendez-vous sont offerts en anglais, ukrainien et russe. Le site français est informatif et n’indique pas une offre de représentation en français.'))]
 return f'''<section class="consultation-hero"><span class="eyebrow">{t('A CLEAR STARTING POINT','UN POINT DE DÉPART CLAIR')}</span><h1>{t('Your first consultation.','Votre première consultation.')}</h1><p>{t('What to ask, what to prepare and how to take the first step with Kostyantyn Mykhalchenko.','Les questions à poser, les éléments à préparer et la première démarche auprès de Kostyantyn Mykhalchenko.')}</p><div class="actions"><a class="button" href="{contact}">{t('Request an appointment','Demander un rendez-vous')}</a><a class="light-link" href="tel:+12898885878">{t('Call','Appeler')} (289) 888-5878</a></div></section><div class="consultation-jumps"><a href="#before-booking">{t('Before booking','Avant de fixer le rendez-vous')}</a><a href="#prepare-consultation">{t('What to prepare','Éléments à préparer')}</a><a href="#after-consultation">{t('Next steps','Prochaines étapes')}</a></div><section class="article-layout consultation-layout"><article><section id="before-booking"><span class="eyebrow">01 / {t('CONFIRM FIRST','CONFIRMER D’ABORD')}</span><h2>{t('Before you book','Avant de fixer le rendez-vous')}</h2><p>{t('Use your first contact to establish the practical arrangements. Fees, meeting length and availability should be confirmed directly with the practice.','Profitez du premier contact pour établir les modalités pratiques. Confirmez les honoraires, la durée et la disponibilité directement avec le cabinet.')}</p><dl class="consultation-details">{''.join('<div><dt>'+h+'</dt><dd>'+p+'</dd></div>' for h,p in rows)}</dl></section><section id="after-consultation"><span class="eyebrow">02 / {t('AGREE ON THE NEXT STEP','CONVENIR DE LA SUITE')}</span><h2>{t('Leave with the right questions answered','Clarifiez la prochaine étape')}</h2><p>{t('Before proceeding, ask which tasks the lawyer can take on, what you will need to do, and how the proposed fees will work. Confirm whether the practice has accepted the matter and how further communication will take place.','Avant de poursuivre, demandez quelles tâches l’avocat peut prendre en charge, ce que vous devrez faire et les modalités des honoraires proposés. Confirmez l’acceptation du dossier et les moyens de communication à utiliser.')}</p><p>{t('An enquiry or appointment request does not confirm representation or change a deadline. If a date is approaching, flag it when you contact the practice.','Une demande de renseignements ou de rendez-vous ne confirme pas la représentation et ne modifie pas une échéance. Signalez toute date proche lors du premier contact.')}</p></section><section class="consultation-questions"><h2>{t('A few practical questions','Quelques questions pratiques')}</h2>{''.join('<details><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in questions)}</section></article><aside class="checklist" id="prepare-consultation"><span class="eyebrow">{t('YOUR PREPARATION LIST','VOTRE LISTE DE PRÉPARATION')}</span><h3>{t('Keep these ready','À garder à portée de main')}</h3><ul>{''.join('<li><label><input type="checkbox"><span>'+x+'</span></label></li>' for x in checklist)}</ul><p class="small">{t('These checks stay on this page. Nothing is saved or sent. Keep sensitive details out of the general enquiry form.','Ces choix restent sur cette page. Rien n’est enregistré ni transmis. N’inscrivez pas de renseignements sensibles dans le formulaire général.')}</p><a class="button" href="{contact}">{t('Send an enquiry','Envoyer une demande')}</a><p class="guide-profile-link">{link('about',t('Meet your lawyer →','Découvrir votre avocat →'),fr)}</p></aside></section>'''

def about_details(fr):
 def t(en,fr_text):return fr_text if fr else en
 topics=[('property','Real estate','Immobilier'),('family','Family & separation','Famille et séparation'),('wills-estates','Wills & estates','Testaments et successions'),('business','Business & contracts','Entreprises et contrats'),('housing','Residential tenancies','Location résidentielle'),('disputes','Civil disputes','Litiges civils'),('criminal-law','Criminal law','Droit criminel')]
 return '<section class="section profile-overview"><div><span class="eyebrow">'+t('WORKING WITH KOSTYANTYN','VOTRE ÉCHANGE AVEC KOSTYANTYN')+'</span><h2>'+t('Start with the matter.<br>Understand the next step.','Présentez votre dossier.<br>Comprenez la prochaine étape.')+'</h2><p>'+t('Kostyantyn is based in Halifax and serves clients across Nova Scotia through Pavel Boubnov – Barrister & Solicitor. Appointments are available in English, Ukrainian and Russian. Confirm the meeting location and format directly with the practice.','Kostyantyn est établi à Halifax et sert des clients partout en Nouvelle-Écosse au sein de Pavel Boubnov – Barrister & Solicitor. Les rendez-vous sont offerts en anglais, ukrainien et russe. Confirmez le lieu et le mode du rendez-vous directement avec le cabinet.')+'</p>'+link('first-consultation',t('Prepare for your first consultation →','Préparez votre première consultation →'),fr)+'</div><div><h3>'+t('Explore the services','Découvrez les services')+'</h3><div class="profile-services">'+''.join(link('topics/'+slug,t(en,french),fr) for slug,en,french in topics)+'</div></div></section>'
